function styleText(s, style){
  var out = "";
  for (var i = 0; i < s.length; i++){
    var c = s.charAt(i), code = s.charCodeAt(i);
    if (style === "fullwidth"){
      if (c === " ") out += "　";
      else if (code >= 33 && code <= 126) out += String.fromCharCode(code + 0xFEE0);
      else out += c;
    } else if (style === "circle"){
      if (c >= "a" && c <= "z") out += String.fromCharCode(0x24D0 + (code - 97));
      else if (c >= "A" && c <= "Z") out += String.fromCharCode(0x24B6 + (code - 65));
      else if (c >= "0" && c <= "9") out += String.fromCharCode(c === "0" ? 0x24EA : 0x2460 + (code - 49));
      else out += c;
    } else if (style === "bubble"){
      if (c >= "A" && c <= "Z") out += String.fromCharCode(0x1F170 + (code - 65));
      else if (code >= 33 && code <= 126) out += String.fromCharCode(code + 0xFEE0);
      else out += c;
    } else out += c;
  }
  return out;
}
var EXPORTS = { styleText: styleText };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BubbleForgePure = EXPORTS; }
